import { useCallback } from 'react';

import { useIntl } from 'react-intl';

import {
  Divider,
  Icon,
  Page,
  SizableText,
  Stack,
  XStack,
  YStack,
} from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import { ListItem } from '@onekeyhq/kit/src/components/ListItem';
import { WalletListView } from '@onekeyhq/kit/src/components/WalletListView';
import {
  navigateToKeyTagBackupDotMapPage,
  navigateToKeyTagEnterPhrasePage,
} from '@onekeyhq/kit/src/hooks/usePageNavigation';
import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import { shouldShowMnemonicBackupEntryForWallet } from '@onekeyhq/kit/src/utils/botWalletStatusUtils';
import type { IDBWallet } from '@onekeyhq/kit-bg/src/dbs/local/types';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import { EReasonForNeedPassword } from '@onekeyhq/shared/types/setting';

import { KeyTagTestIDs } from '../../testIDs';

const ListFooterComponent = ({ walletCount }: { walletCount: number }) => {
  const intl = useIntl();
  const onPress = useCallback(() => {
    navigateToKeyTagEnterPhrasePage();
  }, []);
  return (
    <YStack>
      {walletCount ? (
        <YStack>
          <SizableText size="$bodySm" color="$textSubdued" px="$5" mt="$5">
            {intl.formatMessage({
              id: ETranslations.settings_hardware_wallets_not_appear,
            })}
          </SizableText>
          <XStack px="$5" pt="$5" pb="$4">
            <Divider />
          </XStack>
        </YStack>
      ) : null}
      <ListItem
        icon="PencilOutline"
        title={intl.formatMessage({
          id: ETranslations.global_enter_recovery_phrase,
        })}
        drillIn
        onPress={onPress}
        testID={KeyTagTestIDs.enterRecoveryPhraseItem}
        renderIcon={
          <Stack bg="$bgStrong" p="$2" borderRadius="$3">
            <Icon name="PencilOutline" size="$6" color="$icon" />
          </Stack>
        }
      />
    </YStack>
  );
};

const BackupWallet = () => {
  const intl = useIntl();
  const walletList = usePromiseResult(async () => {
    const { wallets } = await backgroundApiProxy.serviceAccount.getWallets();
    const hdWalletList = wallets.filter((wallet) =>
      shouldShowMnemonicBackupEntryForWallet({
        walletId: wallet.id,
        isKeylessWallet: wallet.isKeyless,
      }),
    );
    return hdWalletList;
  }, []).result;
  const onPick = useCallback(async (item: IDBWallet) => {
    const { mnemonic: encodedText } =
      await backgroundApiProxy.serviceAccount.getHDAccountMnemonic({
        walletId: item.id,
        reason: EReasonForNeedPassword.Security,
      });
    navigateToKeyTagBackupDotMapPage({
      walletId: item.id,
      isWalletBackedUp: item.backuped,
      encodedText,
      title: item.name,
    });
  }, []);
  return (
    <Page>
      <Page.Header
        title={intl.formatMessage({ id: ETranslations.settings_select_wallet })}
      />
      <Page.Body>
        <WalletListView
          walletList={walletList}
          ListFooterComponent={
            <ListFooterComponent walletCount={walletList?.length ?? 0} />
          }
          onPick={onPick}
        />
      </Page.Body>
    </Page>
  );
};

export default BackupWallet;
